name = "exposed"
path = "src/bin/main.rs"


[dependencies]
anyhow = "1.0.104"
axum = "0.8.9"
chrono = { version = "0.4.45", features = ["serde"] }
clap = { version = "4.6.7", features = ["derive"] }
dotenvy = "0.15.7"
rust-yaml = { version = "1.1.0", features = ["serde"] }
serde = { version = "1.0.229", features = ["derive"] }
serde_json = { version = "1.0.151", features = ["arbitrary_precision"] }
sqlx = { version = "0.9.0", features = ["postgres", "runtime-tokio","uuid", "time", "bigdecimal"] }
strum = { version = "0.28.0", features = ["derive", "strum_macros"] }
thiserror = "2.0.20"
tokio = { version = "1.53.1", features = ["rt-multi-thread"] }
reqwest = "0.13.5"
arrow = { version = "60.0.0", features = ["async"] }
parquet = { version = "60.0.0", features = ["arrow", "async"] }
